def specific_criteria(short_id, goal_id):
    if short_id not in CRITERIA or goal_id not in ('G1', 'G2'):
        return {}
    values = CRITERIA[short_id][int(goal_id[1:]) - 1]
    return dict(zip(('activation', 'evidence_required', 'alternatives', 'failure'), values))
